@import url('https://fonts.googleapis.com/css2?family=Bebas+Neue&family=Plus+Jakarta+Sans:wght@300;400;500;600;700&display=swap');
@import "tailwindcss";

@theme {
  --font-heading: 'Bebas Neue', sans-serif;
  --font-body: 'Plus Jakarta Sans', sans-serif;

  --color-accent: #E50914;
  --color-accent-hover: #ff1a25;
  --color-bg-primary: #000000;
  --color-bg-secondary: #141414;
  --color-bg-surface: #1a1a1a;
  --color-text-primary: #FFFFFF;
  --color-text-secondary: #a1a1a1;
  --color-border-subtle: rgba(255, 255, 255, 0.1);
}

html {
  scroll-behavior: smooth;
}

body {
  margin: 0;
  background-color: var(--color-bg-primary);
  color: var(--color-text-primary);
  font-family: var(--font-body);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

#root {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

/* Grain overlay */
.grain::before {
  content: '';
  position: fixed;
  inset: 0;
  opacity: 0.04;
  pointer-events: none;
  z-index: 100;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 512 512' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noise'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.65' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noise)'/%3E%3C/svg%3E");
}

/* Custom scrollbar */
::-webkit-scrollbar {
  width: 6px;
  height: 6px;
}

::-webkit-scrollbar-track {
  background: var(--color-bg-primary);
}

::-webkit-scrollbar-thumb {
  background: #333;
  border-radius: 3px;
}

/* Hide scrollbar for carousel */
.no-scrollbar::-webkit-scrollbar {
  display: none;
}

.no-scrollbar {
  -ms-overflow-style: none;
  scrollbar-width: none;
}

/* Radix accordion animation */
[data-state="open"] .accordion-content {
  animation: slideDown 300ms ease-out;
}

[data-state="closed"] .accordion-content {
  animation: slideUp 300ms ease-out;
}

@keyframes slideDown {
  from {
    height: 0;
    opacity: 0;
  }
  to {
    height: var(--radix-accordion-content-height);
    opacity: 1;
  }
}

@keyframes slideUp {
  from {
    height: var(--radix-accordion-content-height);
    opacity: 1;
  }
  to {
    height: 0;
    opacity: 0;
  }
}

/* Poster card hover */
.poster-card {
  transition: transform 300ms ease, box-shadow 300ms ease;
}

.poster-card:hover {
  transform: scale(1.05);
  box-shadow: 0 8px 30px rgba(0, 0, 0, 0.6);
}

/* Feature card hover */
.feature-card {
  transition: transform 300ms ease, background-color 300ms ease;
}

.feature-card:hover {
  transform: translateY(-4px);
  background-color: rgba(45, 45, 45, 0.8);
}

/* Select dropdown styling */
select option {
  background-color: #1a1a1a;
  color: white;
}

/* Input autofill override */
input:-webkit-autofill,
input:-webkit-autofill:hover,
input:-webkit-autofill:focus {
  -webkit-text-fill-color: white;
  -webkit-box-shadow: 0 0 0px 1000px rgba(0, 0, 0, 0.8) inset;
  transition: background-color 5000s ease-in-out 0s;
}

