import { useState } from "react";
import { motion } from "framer-motion";
import { siteConfig } from "@/config/site";

const mosaicShapes = [
  { top: "5%", left: "3%", w: "14%", h: "55%", bg: "linear-gradient(135deg, #6b0f1a, #3d0a10)", rot: -8, opacity: 0.3 },
  { top: "8%", left: "18%", w: "11%", h: "48%", bg: "linear-gradient(150deg, #b34700, #6b2a00)", rot: 5, opacity: 0.25 },
  { top: "2%", left: "32%", w: "13%", h: "58%", bg: "linear-gradient(120deg, #c2185b, #7b1040)", rot: -3, opacity: 0.27 },
  { top: "6%", left: "48%", w: "12%", h: "42%", bg: "linear-gradient(140deg, #4a148c, #2a0a52)", rot: 7, opacity: 0.25 },
  { top: "0%", left: "62%", w: "14%", h: "52%", bg: "linear-gradient(160deg, #b71c1c, #6b1010)", rot: -6, opacity: 0.3 },
  { top: "10%", left: "78%", w: "13%", h: "48%", bg: "linear-gradient(130deg, #004d40, #00261e)", rot: 4, opacity: 0.22 },
  { top: "52%", left: "8%", w: "12%", h: "45%", bg: "linear-gradient(145deg, #6a1b9a, #3d0f5a)", rot: 6, opacity: 0.2 },
  { top: "50%", left: "25%", w: "14%", h: "48%", bg: "linear-gradient(125deg, #ad1457, #6a0a34)", rot: -5, opacity: 0.22 },
  { top: "58%", left: "50%", w: "11%", h: "42%", bg: "linear-gradient(155deg, #5d4037, #3a2820)", rot: 3, opacity: 0.2 },
  { top: "55%", left: "72%", w: "13%", h: "45%", bg: "linear-gradient(135deg, #1b3a2d, #0d1e16)", rot: -7, opacity: 0.25 },
];

export function Hero() {
  const [email, setEmail] = useState("");
  const { hero } = siteConfig;

  return (
    <section className="relative min-h-screen flex items-center justify-center overflow-hidden">
      {/* Mosaic Background */}
      <div className="absolute inset-0">
        {mosaicShapes.map((shape, i) => (
          <div
            key={i}
            className="absolute"
            style={{
              top: shape.top,
              left: shape.left,
              width: shape.w,
              height: shape.h,
              background: shape.bg,
              transform: `rotate(${shape.rot}deg)`,
              opacity: shape.opacity,
              borderRadius: "4px",
              filter: "blur(2px)",
            }}
          />
        ))}
        {/* Accent glow */}
        <div
          className="absolute inset-0"
          style={{
            background:
              "radial-gradient(ellipse at 50% 40%, rgba(229,9,20,0.08) 0%, transparent 60%)",
          }}
        />
        {/* Dark gradient overlay */}
        <div className="absolute inset-0 bg-gradient-to-b from-black/70 via-black/60 to-black" />
        {/* Bottom fade into next section */}
        <div className="absolute bottom-0 left-0 right-0 h-40 bg-gradient-to-t from-black to-transparent" />
      </div>

      {/* Content */}
      <div className="relative z-10 text-center px-6 max-w-2xl mx-auto">
        <motion.h1
          className="font-heading text-5xl sm:text-6xl md:text-7xl lg:text-8xl tracking-wide text-white leading-[0.9] mb-6"
          initial={{ opacity: 0, y: 30 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.8, delay: 0.2 }}
        >
          {hero.title}
        </motion.h1>

        <motion.p
          className="text-lg md:text-xl text-white/90 mb-2 font-medium"
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.6, delay: 0.5 }}
        >
          {hero.subtitle}
        </motion.p>

        <motion.p
          className="text-base md:text-lg text-white/60 mb-8"
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.6, delay: 0.7 }}
        >
          {hero.prompt}
        </motion.p>

        <motion.form
          className="flex flex-col sm:flex-row gap-3 max-w-xl mx-auto"
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.6, delay: 0.9 }}
          onSubmit={(e) => e.preventDefault()}
        >
          <input
            type="email"
            placeholder={hero.emailPlaceholder}
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            className="flex-1 bg-black/60 border border-white/30 text-white px-4 py-3.5 rounded text-base placeholder:text-muted focus:outline-none focus:border-white focus:ring-1 focus:ring-white"
          />
          <button
            type="submit"
            className="bg-accent hover:bg-accent-hover text-white px-8 py-3.5 rounded font-semibold text-lg flex items-center justify-center gap-2 transition-colors whitespace-nowrap"
          >
            {hero.cta} <span aria-hidden="true">›</span>
          </button>
        </motion.form>
      </div>
    </section>
  );
}

