import { useRef, useState, useEffect } from "react";
import { motion } from "framer-motion";
import { ChevronLeft, ChevronRight } from "lucide-react";
import { siteConfig } from "@/config/site";

export function Trending() {
  const scrollRef = useRef<HTMLDivElement>(null);
  const [showLeftArrow, setShowLeftArrow] = useState(false);
  const [showRightArrow, setShowRightArrow] = useState(true);
  const { trending } = siteConfig;

  const checkArrows = () => {
    if (!scrollRef.current) return;
    const { scrollLeft, scrollWidth, clientWidth } = scrollRef.current;
    setShowLeftArrow(scrollLeft > 10);
    setShowRightArrow(scrollLeft < scrollWidth - clientWidth - 10);
  };

  useEffect(() => {
    checkArrows();
    window.addEventListener("resize", checkArrows);
    return () => window.removeEventListener("resize", checkArrows);
  }, []);

  const scroll = (direction: "left" | "right") => {
    if (!scrollRef.current) return;
    const scrollAmount = scrollRef.current.clientWidth * 0.65;
    scrollRef.current.scrollBy({
      left: direction === "left" ? -scrollAmount : scrollAmount,
      behavior: "smooth",
    });
  };

  return (
    <section className="relative py-16 md:py-20">
      <div className="max-w-[1400px] mx-auto px-6 md:px-12 lg:px-16">
        <motion.h2
          className="font-heading text-3xl md:text-4xl tracking-wide text-white mb-8"
          initial={{ opacity: 0, y: 20 }}
          whileInView={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.6 }}
          viewport={{ once: true }}
        >
          {trending.heading}
        </motion.h2>
      </div>

      <div className="relative max-w-[1400px] mx-auto">
        {/* Left arrow */}
        {showLeftArrow && (
          <button
            onClick={() => scroll("left")}
            className="absolute left-0 top-0 bottom-4 w-12 md:w-16 z-10 flex items-center justify-center bg-gradient-to-r from-black/90 to-transparent"
            aria-label="Scroll left"
          >
            <ChevronLeft className="w-8 h-8 text-white" />
          </button>
        )}

        {/* Carousel */}
        <div
          ref={scrollRef}
          onScroll={checkArrows}
          className="flex gap-4 md:gap-5 overflow-x-auto no-scrollbar px-6 md:px-12 lg:px-16 pb-4"
        >
          {trending.items.map((item, i) => (
            <motion.div
              key={item.rank}
              className="poster-card relative shrink-0 cursor-pointer"
              initial={{ opacity: 0, y: 20 }}
              whileInView={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.4, delay: i * 0.05 }}
              viewport={{ once: true }}
            >
              <div className="relative w-[130px] sm:w-[150px] md:w-[175px] aspect-[2/3] rounded-md overflow-hidden">
                {/* Gradient background (poster placeholder) */}
                <div
                  className="absolute inset-0"
                  style={{
                    background: `linear-gradient(135deg, ${item.gradient[0]}, ${item.gradient[1]})`,
                  }}
                />
                {/* Decorative poster lines */}
                <div className="absolute inset-0 opacity-20">
                  <div className="absolute top-[15%] left-[10%] right-[10%] h-[2px] bg-white/40" />
                  <div className="absolute top-[22%] left-[15%] right-[15%] h-[1px] bg-white/30" />
                  <div className="absolute top-[42%] left-[10%] w-[40%] h-[2px] bg-white/40" />
                  <div className="absolute top-[50%] left-[10%] w-[60%] h-[1px] bg-white/20" />
                  <div className="absolute bottom-[30%] left-[10%] right-[10%] h-[1px] bg-white/30" />
                </div>
                {/* Rank number overlay */}
                <span className="absolute -top-4 -left-2 font-heading text-[7rem] sm:text-[8rem] md:text-[10rem] leading-none text-white/15 select-none pointer-events-none">
                  {item.rank}
                </span>
                {/* Title overlay */}
                <div className="absolute bottom-0 left-0 right-0 p-3 bg-gradient-to-t from-black/80 via-black/40 to-transparent">
                  <p className="text-xs sm:text-sm md:text-base font-semibold text-white">
                    {item.title}
                  </p>
                </div>
              </div>
            </motion.div>
          ))}
        </div>

        {/* Right arrow */}
        {showRightArrow && (
          <button
            onClick={() => scroll("right")}
            className="absolute right-0 top-0 bottom-4 w-12 md:w-16 z-10 flex items-center justify-center bg-gradient-to-l from-black/90 to-transparent"
            aria-label="Scroll right"
          >
            <ChevronRight className="w-8 h-8 text-white" />
          </button>
        )}
      </div>
    </section>
  );
}

