import { useState } from "react";
import { motion } from "framer-motion";
import { siteConfig } from "@/config/site";

export function CTASection() {
  const [email, setEmail] = useState("");
  const { cta } = siteConfig;

  return (
    <section className="py-16 md:py-24 border-t border-white/5">
      <div className="max-w-[600px] mx-auto px-6 text-center">
        <motion.p
          className="text-lg md:text-xl text-white/80 mb-8"
          initial={{ opacity: 0, y: 20 }}
          whileInView={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.6 }}
          viewport={{ once: true }}
        >
          {cta.prompt}
        </motion.p>

        <motion.form
          className="flex flex-col sm:flex-row gap-3"
          initial={{ opacity: 0, y: 20 }}
          whileInView={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.6, delay: 0.2 }}
          viewport={{ once: true }}
          onSubmit={(e) => e.preventDefault()}
        >
          <input
            type="email"
            placeholder={cta.emailPlaceholder}
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            className="flex-1 bg-black/60 border border-white/30 text-white px-4 py-3.5 rounded text-base placeholder:text-muted focus:outline-none focus:border-white focus:ring-1 focus:ring-white"
          />
          <button
            type="submit"
            className="bg-accent hover:bg-accent-hover text-white px-8 py-3.5 rounded font-semibold text-lg flex items-center justify-center gap-2 transition-colors whitespace-nowrap"
          >
            {cta.cta} <span aria-hidden="true">›</span>
          </button>
        </motion.form>
      </div>
    </section>
  );
}

