import { siteConfig } from "@/config/site";

export function Footer() {
  const { footer } = siteConfig;

  return (
    <footer className="bg-surface py-12 md:py-16">
      <div className="max-w-[1000px] mx-auto px-6 md:px-12">
        <p className="text-muted text-sm mb-6">{footer.contactPrompt}</p>

        <div className="grid grid-cols-2 sm:grid-cols-4 gap-y-3 gap-x-4 mb-8">
          {footer.links.flat().map((link, i) =>
            link ? (
              <a
                key={`${link}-${i}`}
                href="#"
                className="text-muted text-xs hover:text-white/70 underline underline-offset-2 transition-colors"
              >
                {link}
              </a>
            ) : null
          )}
        </div>

        <select
          className="bg-transparent border border-white/30 text-white text-sm px-3 py-1.5 rounded mb-6 cursor-pointer"
          aria-label="Language"
          defaultValue="en"
        >
          <option value="en">English</option>
        </select>

        <p className="text-muted/50 text-xs">{footer.legalNote}</p>
      </div>
    </footer>
  );
}

